// @ts-check
// Generates `src-generated/stryker-core.ts` from `schema/stryker-core.json`.
// Port of upstream stryker-js v9.6.1 `tasks/generate-json-schema-to-ts.js`, trimmed to this
// package's single schema. The preprocessing steps are kept verbatim so the emitted file
// matches what upstream generates from the identical schema with json-schema-to-typescript
// pinned to the same version (15.0.4). Run `pnpm generate` after editing the schema, and
// commit the generated file — the build and typecheck need it present.
import { mkdir, readFile, writeFile } from 'fs/promises'
import path from 'path'
import { fileURLToPath } from 'url'

import { compile } from 'json-schema-to-typescript'

const packageRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')

/**
 * @param {any} inputSchema
 */
function preprocessSchema(inputSchema) {
  const cleanedSchema = cleanExternalRef(inputSchema)

  try {
    switch (cleanedSchema.type) {
      case 'object':
        const inputRequired = cleanedSchema.required ?? []
        const outputSchema = {
          ...cleanedSchema,
          properties: preprocessProperties(cleanedSchema.properties),
          definitions: preprocessProperties(cleanedSchema.definitions),
          required: preprocessRequired(cleanedSchema.properties, inputRequired),
        }
        if (cleanedSchema.definitions) {
          outputSchema.definitions = preprocessProperties(cleanedSchema.definitions)
        }
        return outputSchema
      case 'array':
        return {
          ...cleanedSchema,
          items: preprocessSchema(cleanedSchema.items),
        }
      default:
        if (cleanedSchema.$ref) {
          // Workaround for: https://github.com/bcherny/json-schema-to-typescript/issues/193
          return {
            $ref: cleanedSchema.$ref,
          }
        }
        if (cleanedSchema.oneOf) {
          return {
            ...cleanedSchema,
            oneOf: cleanedSchema.oneOf.map(preprocessSchema),
          }
        }
        return cleanedSchema
    }
  } catch (err) {
    throw new Error(`Schema failed: ${JSON.stringify(inputSchema)}`, { cause: err })
  }
}

/**
 * @param {any} inputSchema
 */
function cleanExternalRef(inputSchema) {
  // node 12 doesn't support optional chain yet
  if (inputSchema.$ref && inputSchema.$ref.startsWith('http')) {
    return {
      ...inputSchema,
      $ref: undefined,
    }
  }
  return inputSchema
}

/**
 * @param {any} inputProperties
 */
function preprocessProperties(inputProperties) {
  if (inputProperties) {
    const outputProperties = {}
    // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
    Object.entries(inputProperties).forEach(
      ([name, value]) => (outputProperties[name] = preprocessSchema(value)),
    )
    return outputProperties
  }
}

/**
 * @param {any} inputProperties
 * @param {any} inputRequired
 * @returns
 */
function preprocessRequired(inputProperties, inputRequired) {
  if (inputProperties) {
    // eslint-disable-next-line @typescript-eslint/no-unsafe-argument
    return Object.entries(inputProperties)
      .filter(
        ([name, value]) => 'default' in value || inputRequired.indexOf(name) >= 0,
      )
      .map(([name]) => name)
  } else {
    return inputRequired
  }
}

async function generate() {
  const schemaFile = path.join(packageRoot, 'schema', 'stryker-core.json')
  const outDir = path.join(packageRoot, 'src-generated')
  const outFile = path.join(outDir, 'stryker-core.ts')

  const schema = preprocessSchema(
    JSON.parse(await readFile(schemaFile, 'utf-8')),
  )

  await mkdir(outDir, { recursive: true })

  const ts = await compile(schema, path.basename(schemaFile), {
    style: {
      singleQuote: true,
    },
    $refOptions: {
      resolve: {
        http: false, // We're not interesting in generating exact babel / tsconfig / etc types
      },
    },
    bannerComment: `/**
    * This file was automatically generated by ${path.basename(import.meta.url)}.
    * DO NOT MODIFY IT BY HAND. Instead, modify the source file JSON file: ${path.basename(schemaFile)},
    * and run 'pnpm generate' from the package directory.
    */`,
  })

  await writeFile(outFile, ts, 'utf8')
  console.log(`✅ schema/stryker-core.json -> ${path.relative(packageRoot, outFile)}`)
}

generate().catch((err) => {
  console.error('TS generation failed', err)
  process.exitCode = 1
})
